package com.bank.payments.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.payments.adapters.in.rest.SelectMenuOptionRequest;
import com.bank.payments.adapters.in.rest.SelectMenuOptionResponse;
import com.bank.payments.domain.error.BusinessError;
import org.junit.jupiter.api.Test;

class SelectMenuOptionServiceTest {

    private final SelectMenuOptionService service = new SelectMenuOptionService();

    @Test
    void option_1_opens_payment_orders() {
        SelectMenuOptionResponse response = service.execute(new SelectMenuOptionRequest("1"));

        assertThat(response.action()).isEqualTo("PAGOORD");
    }

    @Test
    void option_9_exits() {
        SelectMenuOptionResponse response = service.execute(new SelectMenuOptionRequest("9"));

        assertThat(response.action()).isNotBlank();
        assertThat(response.action().length()).isLessThanOrEqualTo(10);
        assertThat(response.action()).isNotEqualTo("PAGOORD");
    }

    @Test
    void invalid_option() {
        assertThatThrownBy(() -> service.execute(new SelectMenuOptionRequest("5")))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError error = (BusinessError) e;
                    assertThat(error.code()).isEqualTo("INVALID_OPTION");
                    assertThat(error.legacyCode()).isEqualTo("OTHER");
                    assertThat(error.getMessage()).isEqualTo("OPCION NO VALIDA");
                });
    }

    @Test
    void invalid_option_letter() {
        assertThatThrownBy(() -> service.execute(new SelectMenuOptionRequest("A")))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> assertThat(((BusinessError) e).code()).isEqualTo("INVALID_OPTION"));
    }

    @Test
    void invalid_option_zero() {
        assertThatThrownBy(() -> service.execute(new SelectMenuOptionRequest("0")))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> assertThat(((BusinessError) e).legacyCode()).isEqualTo("OTHER"));
    }

    @Test
    void invalid_option_blank() {
        assertThatThrownBy(() -> service.execute(new SelectMenuOptionRequest(" ")))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> assertThat(((BusinessError) e).code()).isEqualTo("INVALID_OPTION"));
    }
}
